+import assert from 'node:assert/strict';
+import { mkdir, writeFile } from 'node:fs/promises';
+
+const [origin, funderId, evidence] = process.argv.slice(2);
+assert(origin && funderId && evidence);
+await mkdir(evidence, { recursive: true });
+const year = new Date().getUTCFullYear();
+const periods = ['historical', 'current-term', 'current-year'];
+let requests = 0;
+async function get(path, expected = 200) {
+  const response = await fetch(`${origin}${path}`);
+  const body = await response.text();
+  await writeFile(`${evidence}/${++requests}.json`, JSON.stringify({ path, status: response.status, body }, null, 2));
+  assert.equal(response.status, expected, path);
+  return expected === 200 ? JSON.parse(body) : null;
+}
+function includes(period, date) {
+  if (period === 'historical') return true;
+  if (date === null) return false;
+  const instant = new Date(date);
+  return period === 'current-term'
+    ? instant >= new Date('2024-07-09T00:00:00Z')
+    : instant.getUTCFullYear() === year;
+}
+for (const path of ['/members/178', '/members/4613', `/funders/${funderId}`]) {
+  const historical = await get(`${path}?period=historical`);
+  const unwrap = row => row.declaration ?? row;
+  const totals = data => data.summary?.declared_totals ?? data.declared_totals;
+  for (const period of periods) {
+    const selected = await get(`${path}?period=${period}`);
+    assert.equal(selected.period, period);
+    assert.deepEqual(totals(selected), totals(historical), `${path} mandatory totals invariant`);
+    assert.deepEqual(selected.declarations, historical.declarations.filter(row => includes(period, unwrap(row).registered_at)), `${path} ${period} scoped declarations`);
+    assert.equal((selected.summary ?? selected).entry_count, selected.declarations.reduce((count, row) => count + unwrap(row).entries.length, 0));
+    assert.deepEqual(selected.member ?? selected.funder, historical.member ?? historical.funder, `${path} identity invariant`);
+  }
+  assert.deepEqual(await get(path), await get(`${path}?period=current-term`));
+  await get(`${path}?period=invalid`, 400);
+}
+for (const period of periods) {
+  const ranking = await get(`/rankings?period=${period}`);
+  assert.equal(ranking.period, period);
+  for (const board of ['members', 'individuals', 'companies', 'parties']) assert(ranking[board].length <= 10);
+}
+await get('/rankings?period=invalid', 400);
+console.log(`Passed ${requests} real API requests for all periods, default, invalid values, scoped source records, counts, identity, and invariant authoritative totals.`);
*** End Patch"));

